function canBuild(triples: number[][], target: number[]): boolean {
  const n = triples.length;
  for (let mask = 1; mask < 1 << n; mask++) {
    const m = [0, 0, 0];
    for (let i = 0; i < n; i++) {
      if (!(mask & (1 << i))) continue;
      for (let p = 0; p < 3; p++) m[p] = Math.max(m[p], triples[i][p]);
    }
    if (m[0] === target[0] && m[1] === target[1] && m[2] === target[2]) return true;
  }
  return false;
}

