    def canBuild(self, triples: List[List[int]], target: List[int]) -> bool:
        n = len(triples)
        for mask in range(1, 1 << n):
            m = [0, 0, 0]
            for i in range(n):
                if mask >> i & 1:
                    m = [max(m[p], triples[i][p]) for p in range(3)]
            if m == target:
                return True
        return False

