  const hit = [false, false, false];
  for (const t of triples) {
    if (t[0] > target[0] || t[1] > target[1] || t[2] > target[2]) continue;
    for (let p = 0; p < 3; p++) if (t[p] === target[p]) hit[p] = true;
  }
  return hit[0] && hit[1] && hit[2];
}

